<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{Container,Csrf,Database,Request,Response,View};
use App\Repositories\AcademicCatalogRepository;
use App\Services\AccessService;

final class AcademicCatalogController
{
 private function repo():AcademicCatalogRepository{return new AcademicCatalogRepository(Container::get(Database::class)->connection());}
 private function csrf(Request $r):void{if(!Csrf::validate((string)$r->input('_csrf')))Response::abort(419,'CSRF inválido.');}
 public function index(Request $r):void{AccessService::require('academico.catalogos.ver');$x=$this->repo();View::render('admin/academico/catalogos/index',['title'=>'Catálogos académicos','careers'=>$x->careers(),'campuses'=>$x->campuses(),'curricula'=>$x->curricula(),'modalities'=>$x->modalities()]);}
 public function careerForm(Request $r):void{AccessService::require('academico.catalogos.gestionar');$x=$this->repo();$id=(int)$r->input('id');View::render('admin/academico/catalogos/career-form',['title'=>$id?'Editar carrera':'Nueva carrera','career'=>$id?$x->career($id):null,'types'=>$x->careerTypes(),'states'=>$x->careerStates()]);}
 public function careerSave(Request $r):never{$this->csrf($r);AccessService::require('academico.catalogos.gestionar');$d=['id'=>(int)$r->input('id'),'tipo'=>(int)$r->input('tipo_carrera_id'),'estado'=>(int)$r->input('estado_carrera_id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'titulo'=>trim((string)$r->input('titulo_otorgado')),'abreviatura'=>trim((string)$r->input('abreviatura')),'niveles'=>(int)$r->input('numero_niveles'),'inicio'=>trim((string)$r->input('fecha_inicio_vigencia')),'fin'=>trim((string)$r->input('fecha_fin_vigencia')),'activo'=>$r->input('activo')!==null?1:0];if(!$d['estado']||$d['codigo']===''||$d['nombre']==='')Response::abort(422,'Código, nombre y estado son obligatorios.');$this->repo()->saveCareer($d);Response::redirect('/admin/academico/catalogos');}
 public function campusForm(Request $r):void{AccessService::require('academico.catalogos.gestionar');$x=$this->repo();$id=(int)$r->input('id');View::render('admin/academico/catalogos/campus-form',['title'=>$id?'Editar sede':'Nueva sede','campus'=>$id?$x->campus($id):null]);}
 public function campusSave(Request $r):never{$this->csrf($r);AccessService::require('academico.catalogos.gestionar');$d=['id'=>(int)$r->input('id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'descripcion'=>trim((string)$r->input('descripcion')),'activo'=>$r->input('activo')!==null?1:0];if($d['codigo']===''||$d['nombre']==='')Response::abort(422,'Código y nombre de sede son obligatorios.');$this->repo()->saveCampus($d);Response::redirect('/admin/academico/catalogos');}
 public function curriculumForm(Request $r):void{AccessService::require('academico.catalogos.gestionar');$x=$this->repo();$id=(int)$r->input('id');View::render('admin/academico/catalogos/curriculum-form',['title'=>$id?'Editar malla':'Nueva malla curricular','curriculum'=>$id?$x->curriculum($id):null,'careers'=>$x->careers(),'states'=>$x->curriculumStates()]);}
 public function curriculumSave(Request $r):never{$this->csrf($r);AccessService::require('academico.catalogos.gestionar');$d=['id'=>(int)$r->input('id'),'carrera'=>(int)$r->input('carrera_id'),'estado'=>(int)$r->input('estado_malla_id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'version'=>trim((string)$r->input('version')),'descripcion'=>trim((string)$r->input('descripcion')),'inicio'=>trim((string)$r->input('fecha_inicio_vigencia')),'fin'=>trim((string)$r->input('fecha_fin_vigencia')),'activo'=>$r->input('activo')!==null?1:0];if(!$d['carrera']||!$d['estado']||$d['codigo']===''||$d['nombre']===''||$d['inicio']==='')Response::abort(422,'Carrera, estado, código, nombre y fecha de inicio son obligatorios.');$this->repo()->saveCurriculum($d);Response::redirect('/admin/academico/catalogos');}
 public function modalitySave(Request $r):never{$this->csrf($r);AccessService::require('academico.catalogos.gestionar');$d=['id'=>(int)$r->input('id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'descripcion'=>trim((string)$r->input('descripcion')),'activo'=>$r->input('activo')!==null?1:0];if($d['codigo']===''||$d['nombre']==='')Response::abort(422,'Código y nombre de modalidad son obligatorios.');$this->repo()->saveModality($d);Response::redirect('/admin/academico/catalogos');}
}
